import boto3
import json
import os

def get_db_connection_secret(secret_id=None):
    """
    Fetches the database connection secret from AWS Secrets Manager.
    """
    if secret_id is None:
        secret_id = os.environ.get('DB_SECRET_ARN', 'prod/database/master')

    client = boto3.client('secretsmanager', region_name=os.environ.get('AWS_REGION', 'us-east-1'))

    try:
        response = client.get_secret_value(SecretId=secret_id)
        if 'SecretString' in response:
            return json.loads(response['SecretString'])
        else:
            return json.loads(response['SecretBinary'].decode('utf-8'))
    except client.exceptions.ResourceNotFoundException:
        raise ValueError(f"Secret {secret_id} not found.")
    except Exception as e:
        raise RuntimeError(f"Error retrieving secret {secret_id}: {str(e)}")
